-- File: 09-mark-fda-reported.sql
-- Purpose: 標記某筆食安檢舉已通報衛福部食藥署 (FDA)，記錄通報管道與單號
-- When to use: admin UI 故障時，admin 在外部通報 FDA 後手動回填三欄位以維持稽核軌跡
-- Variables to fill:
--   :report_id           — food_safety_reports.id
--   :fda_report_channel  — 通報管道 (varchar(30))，例：'fda_online' / 'phone_1919' / 'local_health_bureau'
--   :fda_reference_no    — FDA 回傳的案件編號或內部追蹤號（text）
-- Audit: 執行後將完整 SQL + 結果貼到 Discord #food-safety-actions channel 留紀錄
-- Generated by B-169 (issue #722) — 2026-05-07
--
-- 規則：
--   - 僅在 fda_reported_at IS NULL 時更新（避免覆蓋既有 FDA 通報紀錄）
--   - 若需修正既有 FDA 紀錄（極少數情境），請另開單；本檔 WHERE 故意鎖死防誤操

BEGIN;

UPDATE food_safety_reports
SET
    fda_reported_at    = now(),
    fda_report_channel = :'fda_report_channel',
    fda_reference_no   = :'fda_reference_no',
    updated_at         = now()
WHERE id = :report_id
  AND fda_reported_at IS NULL
RETURNING id, status, fda_reported_at, fda_report_channel, fda_reference_no;

-- 驗證：完整檢舉狀態 + FDA 三欄位
SELECT
    id,
    target_seller_id,
    target_product_id,
    status,
    acknowledged_at,
    investigating_at,
    resolved_at,
    fda_reported_at,
    fda_report_channel,
    fda_reference_no,
    created_at,
    updated_at
FROM food_safety_reports
WHERE id = :report_id;

-- 預期：fda_reported_at 為剛剛、channel 與 ref_no 為填入值
ROLLBACK; -- 確認後改 COMMIT;
